    reasons, changes = [], []
    if attempt["extraction_fp"] != cfg.extraction_fp():
        reasons.append("settings")
        old, new = attempt["settings"], cfg.settings()
        changes = [f"{k}: {old.get(k)} -> {new[k]}" for k in new if old.get(k) != new[k]]
